<div class="d-flex justify-content-center">
    <div class="form-group">
        <label for="selectValues">Select a value from the list:</label>
        <select class="form-control" id="selectValues" @bind="selectedValue">
            <option value="">-- Select a value --</option>
            @foreach (var value in values)
            {
                <option value="@value">@value</option>
            }
        </select>
    </div>
</div>

<div class="form-group">
    <button class="btn btn-primary" @onclick="SubmitSelectedValue">Submit</button>
</div>

@if (submittedValue != null)
{
    <p>You submitted: @submittedValue</p>
}

@code {
    private List<string> values = new List<string>();
    private string selectedValue = null;
    private string submittedValue = null;

    protected override async Task OnInitializedAsync()
    {
        HttpClient httpClient = new HttpClient();
        values = await httpClient.GetFromJsonAsync<List<string>>("https://example.com/api/values");
    }

    private async Task SubmitSelectedValue()
    {
        if (selectedValue != null)
        {
            HttpClient httpClient = new HttpClient();
            var content = new StringContent(selectedValue);
            var response = await httpClient.PostAsync("https://example.com/api/submit", content);
            if (response.IsSuccessStatusCode)
            {
                submittedValue = selectedValue;
            }
        }
    }
}
