      // Create gradient fill
      let grad = createLinearGradient(0, 0, 0, size);
      grad.addColorStop(0, c);
      grad.addColorStop(1, color(hue + 180, sat, bri, alpha));
      fill(grad);

      // Random shape with animation
      let shapeType = floor(random(4));
      let scale = 1 + sin(frameCount * 0.01 + i * j) * 0.2;
      let offset = random(-size/2, size/2);

