        let y1 = cellY + offset;
        let x2 = cellX + size * scale + offset;
        let y2 = cellY + size * scale + offset;
        triangle(x1, y1, x2, y1, x1, y2);
      } else {
        // Star shape
        let points = 5;
        let radius = size * scale / 2;
        let angle = TWO_PI / points;
        let starX = cellX + cellSize/2;
        let starY = cellY + cellSize/2;
        beginShape();
        for (let a = 0; a < TWO_PI; a += angle) {
          let r = (a * 2) % TWO_PI;
          let r2 = (a * 2 + PI) % TWO_PI;
          let x = starX + cos(r) * radius * (1 + sin(r * 2) * 0.5);
          let y = starY + sin(r) * radius * (1 + sin(r * 2) * 0.5);
          vertex(x, y);
          x = starX + cos(r2) * radius * (1 + sin(r2 * 2) * 0.5);
          y = starY + sin(r2) * radius * (1 + sin(r2 * 2) * 0.5);
          vertex(x, y);
        }
        endShape(CLOSE);
