import React, { useState } from 'react';

const DonorList = () => {
  const [donors, setDonors] = useState([
    { id: 15522, "Credit Card": "None" },
    { id: 16043, "dn_donor_name": "Test Sule", "Credit Card": "None" },
    { id: 24621, "dn_donor_name": "james ridge", "Credit Card": "None" },
  ]);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredDonors = donors.filter(donor => {
    const name = donor["dn_donor_name"]?.toLowerCase() || '';
    const creditCard = donor["Credit Card"]?.toLowerCase() || '';
    return name.includes(searchTerm.toLowerCase()) || creditCard.includes(searchTerm.toLowerCase());
  });

  return (
    <div>
      <input
        type="text"
        placeholder="Search by name or credit card..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <ul>
        {filteredDonors.map(donor => (
          <li key={donor.id}>
            {donor["dn_donor_name"] || donor["Credit Card"]}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default DonorList;
```

